const count = contradictions.length;

const subject = `⚠️ Watchdog: LLM Reasoning Contradiction Detected (${count} case${count !== 1 ? 's' : ''})`;

const lines = contradictions.map((c, i) => [
  `Case ${i + 1}:`,
